#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
namespace IslandSystem {
public static class ActionDemoBuild {
 const string Dir="Assets/IslandSystem/ActionDemo";
 public static void Prepare(){
  Directory.CreateDirectory(Dir+"/Resources");AssetDatabase.Refresh();string path=Dir+"/Animation/UAL2_Standard.fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.animationType=ModelImporterAnimationType.Human;importer.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;importer.materialImportMode=ModelImporterMaterialImportMode.None;var imported=importer.defaultClipAnimations;foreach(var clip in imported){clip.loopTime=false;clip.lockRootRotation=true;clip.lockRootHeightY=true;clip.lockRootPositionXZ=true;}importer.clipAnimations=imported;importer.SaveAndReimport();
  var clips=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).ToArray();File.WriteAllLines("Logs/ActionUAL2Clips.txt",clips.Select(c=>c.name+" "+c.length));var chop=clips.First(c=>c.name.EndsWith("TreeChopping_Loop"));
  var ual1=LocomotionClips();
  string cp=Dir+"/ActionLocomotion.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(cp);if(!controller)controller=AnimatorController.CreateAnimatorControllerAtPath(cp);foreach(var st in controller.layers[0].stateMachine.states)controller.layers[0].stateMachine.RemoveState(st.state);
  string[] names={"Idle","Walk","Run","Jump","Land","Chop"};string[] source={"Idle_Loop","Walk_Loop","Sprint_Loop","Jump_Loop","Jump_Land",""};for(int i=0;i<names.Length;i++){var st=controller.layers[0].stateMachine.AddState(names[i]);st.motion=i==5?chop:ual1.First(c=>c.name.EndsWith("|"+source[i])||c.name==source[i]);if(i==0)controller.layers[0].stateMachine.defaultState=st;}
  var tree=new GameObject("PracticeTree");var visual=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.FindAssets("CommonTree_1 t:Model",new[]{"Assets/Art/External"}).Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileName(p)=="CommonTree_1.fbx")),tree.transform);Normalize(visual,3.5f);var col=tree.AddComponent<CapsuleCollider>();col.height=2.3f;col.center=Vector3.up*1.15f;col.radius=.24f;var target=tree.AddComponent<ChopTarget>();target.crown=visual.transform;
  var logSource=AssetDatabase.FindAssets("Wood_Log t:Model",new[]{"Assets/Art/External/KayKit"}).Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileNameWithoutExtension(p)=="Wood_Log_A");var log=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(logSource));Normalize(log,.65f);var logPrefab=PrefabUtility.SaveAsPrefabAsset(log,Dir+"/DroppedWood.prefab");UnityEngine.Object.DestroyImmediate(log);target.logPrefab=logPrefab;var treePrefab=PrefabUtility.SaveAsPrefabAsset(tree,Dir+"/PracticeTree.prefab");UnityEngine.Object.DestroyImmediate(tree);
  var axe=new GameObject("CartoonAxe");Part(axe,"Handle",new Vector3(0,.23f,0),new Vector3(.04f,.6f,.045f),new Color(.40f,.21f,.08f));Part(axe,"AxeHead",new Vector3(.075f,.48f,0),new Vector3(.27f,.17f,.065f),new Color(.63f,.78f,.80f));var axePrefab=PrefabUtility.SaveAsPrefabAsset(axe,Dir+"/Axe.prefab");UnityEngine.Object.DestroyImmediate(axe);
  var config=new GameObject("Lighthouse Action Adapter");var setup=config.AddComponent<ActionSceneSetup>();setup.controller=controller;setup.treePrefab=treePrefab;setup.axePrefab=axePrefab;setup.chopDuration=chop.length;PrefabUtility.SaveAsPrefabAsset(config,Dir+"/Resources/IslandActionSetup.prefab");UnityEngine.Object.DestroyImmediate(config);AssetDatabase.SaveAssets();Debug.Log("ACTION_PREPARE_OK chop="+chop.name+" duration="+chop.length);
 }
 public static AnimationClip[] LocomotionClips(){
  const string original="Assets/Art/External/Quaternius/UniversalAnimationLibrary/UAL1_Standard.fbx";
  string local=Dir+"/Animation/UAL1_Action.fbx";if(!File.Exists(local))File.Copy(original,local);AssetDatabase.ImportAsset(local);
  var importer=(ModelImporter)AssetImporter.GetAtPath(local);importer.animationType=ModelImporterAnimationType.Human;importer.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;importer.materialImportMode=ModelImporterMaterialImportMode.None;
  var selected=new[]{"Idle_Loop","Walk_Loop","Sprint_Loop","Jump_Loop","Jump_Land"};var clips=importer.defaultClipAnimations.Where(c=>selected.Any(n=>c.name.EndsWith("|"+n)||c.name==n)).ToArray();
  foreach(var clip in clips){clip.loopTime=clip.name.EndsWith("_Loop");clip.loopPose=clip.loopTime;clip.lockRootRotation=true;clip.lockRootHeightY=true;clip.lockRootPositionXZ=true;clip.keepOriginalPositionY=false;clip.heightFromFeet=true;if(clip.name.EndsWith("Sprint_Loop")){// UAL1 sprint is authored on the opposite root axis; preserve its axis and align to +Z.
clip.keepOriginalOrientation=true;clip.rotationOffset=180;}}
  importer.clipAnimations=clips;importer.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(local).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).ToArray();
 }
 public static void FixLocomotion(){var clips=LocomotionClips();var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Dir+"/ActionLocomotion.controller");foreach(var state in controller.layers[0].stateMachine.states){string name=state.state.name;string source=name=="Idle"?"Idle_Loop":name=="Walk"?"Walk_Loop":name=="Run"?"Sprint_Loop":name=="Jump"?"Jump_Loop":name=="Land"?"Jump_Land":null;if(source!=null)state.state.motion=clips.First(c=>c.name.EndsWith("|"+source)||c.name==source);}AssetDatabase.SaveAssets();Debug.Log("ACTION_LOCOMOTION_FIX_READY");}
 static void Normalize(GameObject g,float height){var r=g.GetComponentsInChildren<Renderer>();var b=r[0].bounds;foreach(var item in r)b.Encapsulate(item.bounds);g.transform.localScale*=height/b.size.y;b=r[0].bounds;foreach(var item in r)b.Encapsulate(item.bounds);g.transform.localPosition-=new Vector3(b.center.x,b.min.y,b.center.z);}
 static void Part(GameObject parent,string name,Vector3 position,Vector3 size,Color color){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent.transform);g.transform.localPosition=position;g.transform.localScale=size;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());string path=Dir+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,path);}mat.color=color;mat.SetFloat("_Glossiness",.1f);g.GetComponent<Renderer>().sharedMaterial=mat;}
 public static void Build(){var result=UnityEditor.BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity"},locationPathName="Builds/IslandScratchTrial/IslandScratchTrial.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.Development});if(result.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Action build failed");File.WriteAllText("Logs/ActionBuildSuccess.txt",DateTime.UtcNow.ToString("O"));}
}
}
